import{_ as e,o,c as a,a2 as n}from"./chunks/framework.CfwCq2QB.js";const s="/dev-go-docs/shots/0.2.3/en/light/options-models.png",p=JSON.parse('{"title":"AI models","description":"","frontmatter":{},"headers":[],"relativePath":"en/settings/models.md","filePath":"en/settings/models.md"}'),l={name:"en/settings/models.md"};function i(r,t,d,h,c,m){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="ai-models" tabindex="-1">AI models <a class="header-anchor" href="#ai-models" aria-label="Permalink to &quot;AI models&quot;">​</a></h1><p>In one line: translate with Google, Microsoft (no proxy needed), or any OpenAI-compatible LLM — and configure the translation and chat models separately: fast for translation, strong for chat.</p><h2 id="two-models-two-jobs" tabindex="-1">Two models, two jobs <a class="header-anchor" href="#two-models-two-jobs" aria-label="Permalink to &quot;Two models, two jobs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Config</th><th>Where it&#39;s used</th><th>How to choose</th></tr></thead><tbody><tr><td><strong>Translation model</strong></td><td>Full-page / hover / selection translation (when the engine is &quot;AI model&quot;)</td><td>Built for speed: a fast model without deep thinking — glm-4-flash, qwen-turbo, deepseek-chat</td></tr><tr><td><strong>Chat model</strong></td><td>Selection explain / summarize / polish, and the side panel assistant</td><td>Built for capability: a strong model with tool calling — GLM-4.6, Kimi K2, qwen3-max, or a Coding Plan</td></tr></tbody></table><p>The chat model follows the translation model until you save a separate config; &quot;Follow the translation model again&quot; switches back if you&#39;d rather maintain one.</p><img src="'+s+'" alt="AI model settings"><p><em>Settings → AI models: translation and chat models, configured separately.</em></p><h2 id="what-you-fill-in" tabindex="-1">What you fill in <a class="header-anchor" href="#what-you-fill-in" aria-label="Permalink to &quot;What you fill in&quot;">​</a></h2><p>Three things:</p><ol><li><strong>Provider preset</strong>: Zhipu GLM, the Z.ai / Bailian / Ark Coding Plans, Qwen, Doubao, Ollama (local), or Custom. Picking one fills in the base URL</li><li><strong>Base URL</strong>: up to <code>/v1</code> is enough — <code>/chat/completions</code> is appended automatically</li><li><strong>API key</strong>: stored locally only, <strong>never in backups</strong>; leave it empty for local Ollama (set <code>OLLAMA_ORIGINS=chrome-extension://*</code> so the extension may connect)</li></ol><p><strong>Model</strong> can be picked from the list once the URL and key are in (the list can be fetched automatically); &quot;Test connection&quot; verifies the whole setup in one click.</p><h2 id="custom-instructions-optional" tabindex="-1">Custom instructions (optional) <a class="header-anchor" href="#custom-instructions-optional" aria-label="Permalink to &quot;Custom instructions (optional)&quot;">​</a></h2><p>Append to the system prompt, separately for translation and the assistant:</p><ul><li>Translation: use it as a glossary, e.g. &quot;technical-doc style; never translate Token&quot;</li><li>Assistant: set the tone, e.g. &quot;keep answers short&quot; or &quot;list the steps before acting&quot;</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Coding Plan keys only work with their dedicated base URLs; some plans restrict usage to coding tools — check your plan&#39;s terms</li><li>On Volcano Ark, the model name is the console&#39;s model ID or inference endpoint ID (<code>ep-xxxx</code>)</li><li>The paragraph around the selection and the page title are attached automatically — don&#39;t add them to custom instructions yourself</li></ul>',16)])])}const g=e(l,[["render",i]]);export{p as __pageData,g as default};
